using System.Linq;using UnityEditor;using UnityEngine;using AntColony.Units;
public static class Seat1114Library{public static string Run(){var full=Resources.Load<MeshyNativeLibrary>("MeshyNative/Library");var runtime=Resources.Load<MeshyNativeLibrary>("MeshyNative/Runtime");var clip=full.motions.Single(m=>m.id=="Chair_Sit_Idle_M");foreach(var lib in new[]{full,runtime}){lib.actions=lib.actions.Where(a=>a.action!="MealSeated").Concat(new[]{new MeshyNativeLibrary.ActionBinding{action="MealSeated",motion=clip.id}}).ToArray();if(!lib.motions.Any(m=>m.id==clip.id))lib.motions=lib.motions.Concat(new[]{clip}).ToArray();EditorUtility.SetDirty(lib);}AssetDatabase.SaveAssets();return "Existing Chair_Sit_Idle_M bound; no new generation or retargeting";}}
